// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(this)); }
    function testFuzz_property(bytes32 assertionId) public {
        // Drive through assertionDisputedCallback - it does not revert
        c.assertionDisputedCallback(assertionId);
        // After the call, getAssertionPolicy must have blockAssertion == false
        assertTrue(c.getAssertionPolicy(assertionId).blockAssertion == false);
    }
}

